import sys; sys.path.insert(0,'"'"'/workspace'"'"')
import jax, jax.numpy as jnp, numpy as np, importlib.util
spec = importlib.util.spec_from_file_location("L", sys.argv[1]); L = importlib.util.module_from_spec(spec); spec.loader.exec_module(L)
V, D = 7, 5
key = jax.random.key(0)
W = jax.random.normal(key, (D, V))
h = jax.random.normal(jax.random.key(1), (1, 2, D))
logq = jax.nn.log_softmax(h @ W + 0.8*jax.random.normal(jax.random.key(2), (1,2,V)))
def grad_for(y, mode, corr=None, A=1.0):
    tokens = jnp.array([[0, y]]); mask = jnp.array([[False, True]])
    batch = {"tokens": tokens, "mask": mask, "advantages": jnp.array([A]),
             "sampling_token_logprobs": jnp.array([[logq[0,0,y], 0.]])}
    if mode == "full": batch["sampling_vocab_logprobs"] = logq
    if mode == "top3":
        lp, ids = jax.lax.top_k(logq, 3); batch |= {"sampler_topk_ids": ids, "sampler_topk_logprobs": lp}
    f = lambda W: L.loss_fn_rl(h, lambda x: x @ W, batch, corr)[0]
    return jax.grad(f)(W)
q0 = np.exp(np.asarray(logq[0,0]))
for mode in ["none", "top3", "full"]:
    for corr in [None, L.ISCorrection(high=2.0, outside="clamp"), L.ISCorrection(low=0.8, high=1.2, sign="ppo")]:
        g = sum(q0[y]*grad_for(y, mode, corr) for y in range(V))
        g1 = grad_for(0, mode, corr)
        print(mode, corr and corr.sign, "E-grad norm %.2e   single-sample norm %.2e" % (jnp.linalg.norm(g), jnp.linalg.norm(g1)))
